insert into public.question_bank (code, lesson_id, type, level, content, answer_number, tolerance, unit, explanation, formula, remember, points, source, status, sort_order) values ('B18-05', (select l.id from public.lessons l join public.chapters c on c.id = l.chapter_id join public.textbooks t on t.id = c.textbook_id where t.code = 'KHTN9-KNTT-HH' and l.number = 18), 'short_answer', 'van_dung', 'Cho 6,5 g kẽm (Zn = 65) tác dụng hết với dung dịch HCl dư. Thể tích khí hydrogen thu được ở điều kiện chuẩn (24,79 L/mol) là bao nhiêu lít? (làm tròn đến hai chữ số thập phân)', 2.48, 0.01, 'L', 'Zn + 2HCl → ZnCl₂ + H₂; n(Zn) = 6,5/65 = 0,1 mol → n(H₂) = 0,1 mol → V = 0,1·24,79 ≈ 2,48 L.', 'V = n·24,79', null, 1, 'KHTN 9 – câu hỏi mẫu', 'published', 5) on conflict (code) do update set lesson_id = excluded.lesson_id, type = excluded.type, level = excluded.level, content = excluded.content, answer_number = excluded.answer_number, tolerance = excluded.tolerance, unit = excluded.unit, explanation = excluded.explanation, formula = excluded.formula, remember = excluded.remember, sort_order = excluded.sort_order;
